    ctx.beginPath(); ctx.moveTo(X(1.5), Y(MOULD_Y0)); ctx.lineTo(X(SHELL_W - 1.5), Y(MOULD_Y0)); ctx.stroke();
    ctx.strokeStyle = hexToRgba(SHELL_EDGE, 0.5);
