    ctx.moveTo(X(APRON_TOP_X0), Y(APRON_Y0));
    ctx.lineTo(X(APRON_TOP_X1), Y(APRON_Y0));
    ctx.lineTo(X(APRON_BOT_X1), Y(APRON_SHOULDER_Y));
    ctx.lineTo(X(APRON_BOT_X1), Y(SHELL_H - 1.2));
    ctx.lineTo(X(APRON_BOT_X0), Y(SHELL_H - 1.2));
    ctx.lineTo(X(APRON_BOT_X0), Y(APRON_SHOULDER_Y));
    ctx.closePath();
