    var px = Math.max(3, Math.round(mm(KNURL_PITCH) * dpr)), key = px + ':' + dpr;
    if (knurl && knurlKey === key) return knurl;
    var tc = document.createElement('canvas'); tc.width = tc.height = px;
    var k = tc.getContext('2d'), h = px / 2;
    k.fillStyle = 'rgba(255,255,255,0.55)';
    k.beginPath(); k.moveTo(h, 0); k.lineTo(h, h); k.lineTo(0, h); k.closePath(); k.fill();
    k.fillStyle = 'rgba(255,255,255,0.25)';
    k.beginPath(); k.moveTo(h, 0); k.lineTo(px, h); k.lineTo(h, h); k.closePath(); k.fill();
    k.fillStyle = 'rgba(40,44,52,0.22)';
    k.beginPath(); k.moveTo(0, h); k.lineTo(h, h); k.lineTo(h, px); k.closePath(); k.fill();
    k.fillStyle = 'rgba(40,44,52,0.40)';
    k.beginPath(); k.moveTo(h, h); k.lineTo(px, h); k.lineTo(h, px); k.closePath(); k.fill();
