    ctx.fillStyle = LAB_STRIPE; ctx.fillRect(X(LAB_X0), Y(STRIP_Y1 - 2.6), mm(lw), mm(1.8));
    ctx.fillStyle = LAB_INK; ctx.fillRect(X(LAB_X0), Y(STRIP_Y1 - 0.8), mm(lw), mm(0.8));
