    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    ctx.strokeStyle = 'rgba(255,255,255,' + (0.42 * view.s).toFixed(3) + ')'; ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
